<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import AppIcon from '@/components/AppIcon.vue'
import AppModal from '@/components/AppModal.vue'
import ModuleDemoContext from '@/components/ModuleDemoContext.vue'
import { demoMode } from '@/services/quality'
import { supportState as state, currentOffice, companyMode, requestLabels, missionLabels, approvedLead, requestTransition, missionTransition, persist, event, uid, type Mission, type MissionStatus, type ServiceRequest, type RequestStatus, type Visit, type Deliverable } from '@/services/supportDemo'
const route=useRoute();const requestPage=computed(()=>route.path.endsWith('portefeuille-accompagnement'))
const query=ref('');const filter=ref('');const page=ref(1);const view=ref('missions');const error=ref('');const notice=ref('')
const missionOpen=ref(false);const requestOpen=ref(false);const editor=ref(false);const confirmation=ref(false);const kind=ref('request');const tab=ref('Vue d’ensemble');const selectedMission=ref<Mission|null>(null);const selectedRequest=ref<ServiceRequest|null>(null);const version=ref(0);const message=ref('');const command=ref('');const actionTitle=ref('');const comment=ref('')
const form=ref({title:'',description:'',theme:'Qualité & procédures',contact:'',availability:'',urgency:'Normale',objectives:'',scope:'Accompagnement qualité',leadId:'',start:'',end:'',mode:'Présentiel',content:'',reason:''})
const selectedVisit=ref<Visit|null>(null);const selectedDeliverable=ref<Deliverable|null>(null)
const officeName=(id:string)=>state.offices.find(o=>o.id===id)?.name||''
const inScope=(id:string)=>companyMode.value||id===currentOffice.value.id
const visibleMissions=computed(()=>state.missions.filter(m=>inScope(m.officeId)&&(companyMode.value||m.status!=='draft')))
const visibleRequests=computed(()=>state.requests.filter(r=>inScope(r.officeId)&&(companyMode.value?r.status!=='draft':true)))
const normalized=(s:string)=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase()
const match=(s:string)=>normalized(s).includes(normalized(query.value))
const filteredMissions=computed(()=>visibleMissions.value.filter(m=>(!filter.value||m.status===filter.value)&&match(m.title+' '+m.id+' '+officeName(m.officeId))))
const filteredRequests=computed(()=>visibleRequests.value.filter(r=>(!filter.value||r.status===filter.value)&&match(r.title+' '+r.id+' '+officeName(r.officeId))))
const listing=computed(()=>requestPage.value?filteredRequests.value:filteredMissions.value)
const pages=computed(()=>Math.max(1,Math.ceil(listing.value.length/6)))
const missionsPage=computed(()=>filteredMissions.value.slice((page.value-1)*6,page.value*6))
const requestsPage=computed(()=>filteredRequests.value.slice((page.value-1)*6,page.value*6))
const visits=computed(()=>visibleMissions.value.flatMap(m=>m.visits.map(v=>({...v,mission:m}))).sort((a,b)=>a.start.localeCompare(b.start)))
const stats=computed(()=>[{label:'Missions en cours',value:visibleMissions.value.filter(m=>m.status==='active').length,icon:'support'},{label:'Demandes en attente',value:visibleRequests.value.filter(r=>['submitted','triage'].includes(r.status)).length,icon:'clock'},{label:'Visites à venir',value:visits.value.filter(v=>v.status==='confirmed'&&new Date(v.start+'+01:00')>new Date()).length,icon:'calendar'}])
const missionEvents=computed(()=>state.events.filter(e=>e.officeId===selectedMission.value?.officeId&&e.target===selectedMission.value?.id))
const eligibleLeads=computed(()=>currentOffice.value.assignments.filter(a=>a.status==='approved'&&a.scope===form.value.scope))
watch([query,filter,requestPage],()=>{page.value=1})
watch([()=>state.selectedOffice,()=>state.persona],()=>{missionOpen.value=false;requestOpen.value=false;editor.value=false;confirmation.value=false;filter.value='';query.value='';notice.value='';page.value=1})
function attempt(fn:()=>void){error.value='';try{fn()}catch(e){error.value=(e as Error).message}}
function openMission(m:Mission){selectedMission.value=m;version.value=m.version;tab.value='Vue d’ensemble';missionOpen.value=true;error.value='';comment.value=''}
function openRequest(r:ServiceRequest){selectedRequest.value=r;version.value=r.version;requestOpen.value=true;error.value=''}
function newEditor(type:string){kind.value=type;error.value='';form.value={title:'',description:'',theme:'Qualité & procédures',contact:currentOffice.value.email,availability:'',urgency:'Normale',objectives:'',scope:'Accompagnement qualité',leadId:currentOffice.value.assignments.find(a=>a.status==='approved')?.id||'',start:'',end:'',mode:'Présentiel',content:'',reason:''};editor.value=true}
function editDraftRequest(){const r=selectedRequest.value!;newEditor('request');Object.assign(form.value,{title:r.title,description:r.description,theme:r.theme,contact:r.contact,availability:r.availability,urgency:r.urgency})}
function editDraftMission(){const m=selectedMission.value!;newEditor('mission-edit');Object.assign(form.value,{title:m.title,objectives:m.objectives,scope:m.scope,leadId:m.leadId,start:m.start,end:m.end})}
function confirm(action:string,title:string){command.value=action;actionTitle.value=title;message.value='';error.value='';confirmation.value=true}
function save(draft=false){attempt(()=>{
 if(currentOffice.value.status!=='active')throw new Error('L’officine doit être active.')
 const f=form.value
 if(kind.value==='request'){
  if(!draft&&(!f.title.trim()||!f.description.trim()||!f.contact.trim()))throw new Error('Intitulé, description et contact sont requis.')
  const existing=selectedRequest.value; if(existing && (existing.status!=='draft'||existing.officeId!==currentOffice.value.id))throw new Error('Ce brouillon n’est pas modifiable.');
  const r:ServiceRequest={id:existing?.id||uid('DEM'),officeId:currentOffice.value.id,title:f.title||'Demande sans titre',theme:f.theme,description:f.description,contact:f.contact,availability:f.availability,urgency:f.urgency,status:'draft',message:'',created:new Date().toISOString().slice(0,10),version:1}
  if(existing){Object.assign(existing,r);event(r.officeId,r.id,'Brouillon de demande modifié')}else{state.requests.push(r);event(r.officeId,r.id,'Brouillon de demande créé')};if(!draft)requestTransition(existing||r,'submitted');persist();notice.value=draft?'Brouillon fictif enregistré.':'Demande fictive soumise — aucun email envoyé.'
 }else if(kind.value==='mission'||kind.value==='mission-edit'){
  if(!companyMode.value)throw new Error('Utilisez la vue coordination pour proposer une mission.')
  if(!f.title.trim()||!f.objectives.trim()||!f.leadId||!f.start||!f.end||f.end<f.start)throw new Error('Titre, objectifs, responsable et période valide requis.')
  const r=kind.value==='mission'?selectedRequest.value:null
  if(r&&r.officeId!==currentOffice.value.id)throw new Error('Sélectionnez l’officine de cette demande dans le sélecteur avant de créer sa mission.')
  if(r?.status==='converted')throw new Error('Cette demande est déjà convertie.')
  const previous=kind.value==='mission-edit'?selectedMission.value:null
  if(previous&&(previous.status!=='draft'||previous.version!==version.value||previous.officeId!==currentOffice.value.id))throw new Error('Mission non modifiable ou version périmée.');
  const m:Mission={id:previous?.id||uid('MIS'),officeId:currentOffice.value.id,requestId:r?.id,title:f.title,objectives:f.objectives,scope:f.scope,leadId:f.leadId,start:f.start,end:f.end,status:'draft',version:1,visits:[],diagnosis:[{question:'Question de démonstration à définir avec votre méthode',answer:'not_evaluated',reason:''}],diagnosisShared:false,deliverables:[],comments:[],summary:'',openActionsDecision:''}
  if(previous){Object.assign(previous,{title:f.title,objectives:f.objectives,scope:f.scope,leadId:f.leadId,start:f.start,end:f.end,version:previous.version+1});version.value=previous.version;event(m.officeId,m.id,'Brouillon de mission révisé')}else{state.missions.push(m);event(m.officeId,m.id,'Mission créée en brouillon')};if(r){r.status='converted';r.version++;event(r.officeId,r.id,'Demande convertie en mission '+m.id)}persist();requestOpen.value=false;notice.value='Mission fictive créée en brouillon. Ouvrez-la pour la proposer.'
 }else{
  const m=selectedMission.value!;if(!companyMode.value||(kind.value==='summary'?m.status!=='review':m.status!=='active')||!approvedLead(m))throw new Error('État de mission compatible et accès approuvé requis pour intervenir.')
  if(kind.value==='visit'){
   if(!f.title.trim()||!f.start||!f.end||f.end<=f.start)throw new Error('Objet et horaires valides requis (fin après début).')
   m.visits.push({id:uid('VIS'),title:f.title,start:f.start,end:f.end,mode:f.mode,status:'proposed',report:'',history:[]});event(m.officeId,m.id,'Intervention proposée : '+f.title)
  }else if(kind.value==='reschedule'){
   const v=selectedVisit.value!;if(!['confirmed','proposed'].includes(v.status))throw new Error('Cette intervention ne peut plus être reportée.')
   if(!f.reason.trim()||!f.start||!f.end||f.end<=f.start)throw new Error('Nouveaux horaires et motif requis.')
   v.history.push(`${v.start} → ${v.end} : report — ${f.reason}`);v.status='rescheduled';m.visits.push({...v,id:uid('VIS'),start:f.start,end:f.end,status:'proposed',history:[`Issue de ${v.id}`]});event(m.officeId,m.id,'Intervention reportée — '+f.reason)
  }else if(kind.value==='deliverable'){
   if(!f.title.trim()||!f.content.trim())throw new Error('Titre et contenu requis.')
   m.deliverables.push({id:uid('LIV'),title:f.title,content:f.content,version:1,status:'shared',decision:''});event(m.officeId,m.id,'Livrable fictif partagé : '+f.title)
  }else if(kind.value==='summary'){
   if(!f.content.trim()||!f.reason.trim())throw new Error('Synthèse et décision sur les actions ouvertes requises.')
   m.summary=f.content;m.openActionsDecision=f.reason;event(m.officeId,m.id,'Bilan partagé et décision sur les actions ouvertes enregistrée')
  }
  persist();notice.value='Enregistrement fictif effectué.'
 }
 editor.value=false
})}
function execute(){attempt(()=>{
 if(command.value.startsWith('request:'))requestTransition(selectedRequest.value!,command.value.split(':')[1] as RequestStatus,message.value,version.value)
 else if(command.value.startsWith('mission:'))missionTransition(selectedMission.value!,command.value.split(':')[1] as MissionStatus,message.value,version.value)
 else if(command.value==='diagnosis'){
  const m=selectedMission.value!;if(!companyMode.value||m.status!=='active'||!approvedLead(m))throw new Error('Accès approuvé et mission en cours requis.')
  if(m.diagnosis.some(d=>d.answer==='not_applicable'&&!d.reason.trim()))throw new Error('Justifiez chaque réponse « Non applicable ».')
  m.diagnosisShared=true;event(m.officeId,m.id,'Diagnostic fictif partagé — version de démonstration figée');persist()
 }else if(command.value==='visit-confirm'){
  const v=selectedVisit.value!;if(companyMode.value||v.status!=='proposed')throw new Error('Confirmation réservée à la vue officine.');v.status='confirmed';event(selectedMission.value!.officeId,selectedMission.value!.id,'Intervention confirmée');persist()
 }else if(command.value==='visit-cancel'){
  const v=selectedVisit.value!;if(!message.value.trim())throw new Error('Un motif est requis.');if(!['confirmed','proposed'].includes(v.status))throw new Error('Intervention non modifiable.');v.history.push('Annulation : '+message.value);v.status='cancelled';event(selectedMission.value!.officeId,selectedMission.value!.id,'Intervention annulée — '+message.value);persist()
 }else if(command.value==='visit-complete'){
  const v=selectedVisit.value!;if(!companyMode.value||!approvedLead(selectedMission.value!)||v.status!=='confirmed'||!message.value.trim())throw new Error('Accès approuvé, intervention confirmée et compte rendu requis.');v.report=message.value;v.status='completed';event(selectedMission.value!.officeId,selectedMission.value!.id,'Intervention réalisée — compte rendu fictif partagé');persist()
 }else if(command.value.startsWith('deliverable:')){
  const d=selectedDeliverable.value!;if(companyMode.value||d.status!=='shared')throw new Error('Décision non autorisée.');if(command.value==='deliverable:refused'&&!message.value.trim())throw new Error('Motif requis.');d.status=command.value.split(':')[1] as 'accepted'|'refused';d.decision=message.value;event(selectedMission.value!.officeId,selectedMission.value!.id,'Décision sur le livrable : '+d.title);persist()
 }
 confirmation.value=false;version.value=selectedMission.value?.version||selectedRequest.value?.version||0
 if(command.value.startsWith('request:'))version.value=selectedRequest.value!.version
 notice.value='Décision fictive enregistrée. Aucun email envoyé.'
})}
function saveDiagnosisDraft(){attempt(()=>{const m=selectedMission.value!;if(!companyMode.value||m.diagnosisShared||m.status!=='active'||!approvedLead(m))throw new Error('Diagnostic non modifiable.');event(m.officeId,m.id,'Brouillon de diagnostic enregistré');persist();notice.value='Brouillon fictif enregistré, non partagé.'})}
function sendComment(){attempt(()=>{if(!comment.value.trim())throw new Error('Saisissez un message.');const m=selectedMission.value!;if(['closed','refused'].includes(m.status))throw new Error('Cette mission ne permet plus de nouveaux échanges.');m.comments.push({id:uid('COM'),text:comment.value.trim(),author:companyMode.value?'Coordination · démo':'Officine · démo',date:new Date().toISOString()});event(m.officeId,m.id,'Message partagé');persist();comment.value=''})}
const visitLabels:Record<Visit['status'],string>={proposed:'Proposée',confirmed:'Confirmée',completed:'Réalisée',rescheduled:'Reportée',cancelled:'Annulée'}
const answerLabels={not_evaluated:'Non évalué',conform:'Conforme (interne)',gap:'Écart observé',not_applicable:'Non applicable'}
function day(value:string){return value?new Date(value.length===10?value+'T12:00:00+01:00':value.includes('Z')?value:value+'+01:00').toLocaleDateString('fr-FR',{timeZone:'Africa/Porto-Novo',day:'2-digit',month:'short',year:'numeric'}):'—'}
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">ACCOMPAGNEMENT DES OFFICINES</p><h1>{{requestPage?'Demandes de prestation':'Mon accompagnement'}}</h1><p class="page-subtitle">{{requestPage?'Du besoin exprimé à une mission partagée.':'Vos missions, interventions et livrables, dans un même espace.'}}</p></div><div v-if="demoMode" class="heading-actions"><button v-if="!companyMode" class="button primary" @click="selectedRequest=null;newEditor('request')"><AppIcon name="plus" :size="16"/>Demander un accompagnement</button><button v-else class="button primary" @click="selectedRequest=null;newEditor('mission')"><AppIcon name="plus" :size="16"/>Nouvelle mission</button></div></div>
<div v-if="!demoMode" class="panel form-body"><h2>Module 02 · aperçu disponible en démonstration</h2><p>Les missions, diagnostics, interventions et livrables ne sont pas encore reliés à une API. Aucune donnée fictive n’est présentée comme une donnée serveur. Utilisez l’aperçu « Démonstration locale » pour explorer ces parcours.</p><RouterLink to="/dashboard/portefeuille-accompagnement" class="button primary">Demandes d’accompagnement connectées</RouterLink></div>
<template v-else><ModuleDemoContext/><p v-if="notice" role="status" class="alert success">{{notice}}</p><div class="stats-grid"><div v-for="s in stats" :key="s.label" class="stat-card"><span class="stat-top">{{s.label}}<span class="stat-icon"><AppIcon :name="s.icon" :size="18"/></span></span><strong>{{s.value}}</strong><span class="stat-note">{{companyMode?'Portefeuille fictif autorisé':'Officine sélectionnée'}} · {{day(new Date().toISOString())}}</span></div></div>
<div class="panel"><div class="erp-tabs" v-if="!requestPage"><button :class="{selected:view==='missions'}" @click="view='missions'">Missions <small>{{visibleMissions.length}}</small></button><button :class="{selected:view==='calendar'}" @click="view='calendar'">Planning des interventions</button><RouterLink to="/dashboard/portefeuille-accompagnement">Demandes de prestation <AppIcon name="arrow" :size="13"/></RouterLink></div>
<div class="table-toolbar"><label class="search-field"><AppIcon name="search" :size="17"/><input v-model="query" :placeholder="requestPage?'Rechercher une demande…':'Rechercher une mission…'" :aria-label="requestPage?'Rechercher une demande':'Rechercher une mission'"/></label><div class="filter-row"><label class="sr-only" for="support-filter">Filtrer par statut</label><select v-if="requestPage || view==='missions'" id="support-filter" v-model="filter"><option value="">Tous les statuts</option><option v-for="(label,key) in requestPage?requestLabels:missionLabels" :value="key" :key="key">{{label}}</option></select><span class="result-count">{{requestPage?filteredRequests.length:filteredMissions.length}} résultat(s)</span></div></div>
<div v-if="requestPage" class="table-scroll"><table><thead><tr><th>DEMANDE</th><th>OFFICINE</th><th>THÈME</th><th>SOUMISSION</th><th>STATUT</th><th>ACTION</th></tr></thead><tbody><tr v-for="r in requestsPage" :key="r.id"><td><button class="table-title" @click="openRequest(r)">{{r.title}}</button><span class="table-subtitle">{{r.id}}</span></td><td>{{officeName(r.officeId)}}</td><td>{{r.theme}}</td><td>{{day(r.created)}}</td><td><span class="status-badge" :class="r.status">{{requestLabels[r.status]}}</span></td><td><button class="button secondary small" @click="openRequest(r)">Ouvrir</button></td></tr><tr v-if="!requestsPage.length"><td colspan="6" class="empty-state">Aucune demande pour ces critères.</td></tr></tbody></table></div>
<div v-else-if="view==='missions'" class="table-scroll"><table><thead><tr><th>MISSION</th><th>OFFICINE / RESPONSABLE</th><th>PÉRIODE</th><th>ÉTAT</th><th>PROCHAINE INTERVENTION</th><th>ACTION</th></tr></thead><tbody><tr v-for="m in missionsPage" :key="m.id"><td><button class="table-title" @click="openMission(m)">{{m.title}}</button><span class="table-subtitle">{{m.id}} · Version {{m.version}}</span></td><td>{{officeName(m.officeId)}}<span class="table-subtitle">{{state.offices.find(o=>o.id===m.officeId)?.assignments.find(a=>a.id===m.leadId)?.name||'À affecter'}}</span></td><td>{{day(m.start)}}<span class="table-subtitle">au {{day(m.end)}}</span></td><td><span class="status-badge" :class="m.status">{{missionLabels[m.status]}}</span></td><td>{{day(m.visits.filter(v=>v.status==='confirmed'&&new Date(v.start+'+01:00')>new Date()).sort((a,b)=>a.start.localeCompare(b.start))[0]?.start||'')}}</td><td><button class="button secondary small" @click="openMission(m)">Ouvrir</button></td></tr><tr v-if="!missionsPage.length"><td colspan="6" class="empty-state">Aucune mission pour ces critères. Les brouillons ne sont visibles qu’en vue coordination.</td></tr></tbody></table></div>
<div v-else class="visit-list"><article v-for="v in visits.filter(v=>match(v.title+' '+v.mission.title))" :key="v.id" class="visit-card"><div class="visit-date"><strong>{{v.start.slice(8,10)}}</strong><small>{{day(v.start).split(' ').slice(1).join(' ')}}</small></div><div><h3>{{v.title}}</h3><p>{{v.mission.title}} · {{v.mode}} · {{v.start.slice(11)}}–{{v.end.slice(11)}} (Africa/Porto-Novo)</p></div><span class="status-badge" :class="v.status">{{visitLabels[v.status]}}</span><button class="button secondary small" @click="openMission(v.mission);tab='Visites'">Ouvrir</button></article><p v-if="!visits.length" class="empty-state">Aucune intervention planifiée.</p></div>
<div class="panel-foot"><AppIcon name="info" :size="14"/>Données fictives · pas d’inspection officielle<span v-if="requestPage||view==='missions'" class="pagination"><button class="icon-button" :disabled="page<=1" aria-label="Page précédente" @click="page--">‹</button>{{page}} / {{pages}}<button class="icon-button" :disabled="page>=pages" aria-label="Page suivante" @click="page++">›</button></span></div></div>
<div class="module-callout"><AppIcon name="quality" :size="23"/><div><strong>Accompagner, sans se substituer au régulateur</strong><p>Diagnostics et bilans internes ne valent ni inspection ABMed, ni certification. Grilles et méthodes restent à valider avec vous.</p></div></div>
<AppModal v-model="requestOpen" :title="selectedRequest?.title||'Demande de prestation'" size="wide"><div v-if="selectedRequest" class="form-body"><div class="detail-meta"><span>{{selectedRequest.id}} · v{{selectedRequest.version}}</span><span class="status-badge" :class="selectedRequest.status">{{requestLabels[selectedRequest.status]}}</span></div><dl class="application-summary"><dt>Officine</dt><dd>{{officeName(selectedRequest.officeId)}}</dd><dt>Thème</dt><dd>{{selectedRequest.theme}}</dd><dt>Besoin exprimé</dt><dd>{{selectedRequest.description||'Brouillon à compléter'}}</dd><dt>Contact</dt><dd>{{selectedRequest.contact}}</dd><dt>Disponibilité</dt><dd>{{selectedRequest.availability||'À convenir'}}</dd><dt>Urgence déclarée</dt><dd>{{selectedRequest.urgency}} — aucun délai garanti</dd></dl><div v-if="selectedRequest.message" class="review-note"><strong>Dernier message partagé</strong><p>{{selectedRequest.message}}</p></div></div><template #footer><button class="button secondary" @click="requestOpen=false">Fermer</button><template v-if="selectedRequest"><template v-if="companyMode"><button v-if="selectedRequest.status==='submitted'" class="button primary" @click="confirm('request:triage','Prendre en charge la demande')">Prendre en charge</button><template v-if="selectedRequest.status==='triage'"><button class="button secondary" @click="confirm('request:clarifications','Demander des précisions')">Demander des précisions</button><button class="button danger" @click="confirm('request:refused','Refuser la demande')">Refuser</button><button class="button primary" @click="newEditor('mission')">Proposer une mission</button></template></template><template v-else><button v-if="['draft','submitted','clarifications'].includes(selectedRequest.status)" class="button secondary" @click="confirm('request:withdrawn','Retirer la demande')">Retirer</button><button v-if="selectedRequest.status==='draft'" class="button secondary" @click="editDraftRequest">Modifier le brouillon</button><button v-if="selectedRequest.status==='draft'" class="button primary" @click="confirm('request:submitted','Soumettre la demande')">Soumettre</button><button v-if="selectedRequest.status==='clarifications'" class="button primary" @click="confirm('request:submitted','Répondre et renvoyer')">Répondre et renvoyer</button></template></template></template></AppModal>
<AppModal v-model="missionOpen" :title="selectedMission?.title||'Mission'" size="wide"><template v-if="selectedMission"><div class="mission-modal-header"><div class="detail-meta"><span>{{selectedMission.id}} · {{officeName(selectedMission.officeId)}} · v{{selectedMission.version}}</span><span class="status-badge" :class="selectedMission.status">{{missionLabels[selectedMission.status]}}</span></div><div class="erp-tabs"><button v-for="t in ['Vue d’ensemble','Équipe','Diagnostic','Plan et actions','Visites','Livrables','Échanges','Historique']" :key="t" :class="{selected:tab===t}" @click="tab=t;error=''">{{t}}</button></div></div><div class="form-body mission-body"><p v-if="error" class="alert error" role="alert">{{error}}</p>
<template v-if="tab==='Vue d’ensemble'"><dl class="application-summary"><dt>Objectifs</dt><dd>{{selectedMission.objectives}}</dd><dt>Périmètre</dt><dd>{{selectedMission.scope}}</dd><dt>Période prévue</dt><dd>{{day(selectedMission.start)}} → {{day(selectedMission.end)}}</dd><dt>Accès du responsable</dt><dd>{{approvedLead(selectedMission)?'Affectation approuvée et compatible':'Accès non approuvé, hors période ou portée incompatible'}}</dd><dt>Source</dt><dd>{{selectedMission.requestId||'Proposition de l’entreprise'}}</dd></dl><div v-if="selectedMission.summary" class="review-note"><strong>Bilan partagé</strong><p>{{selectedMission.summary}}</p><strong>Actions ouvertes</strong><p>{{selectedMission.openActionsDecision}}</p></div><p class="module-disclaimer">Une proposition de mission ne constitue ni contrat ni facture. Une acceptation ne crée pas de droit d’accès.</p></template>
<template v-else-if="tab==='Équipe'"><h3>Responsable de mission</h3><article class="role-card"><strong>{{state.offices.find(o=>o.id===selectedMission!.officeId)?.assignments.find(a=>a.id===selectedMission!.leadId)?.name||'Non affecté'}}</strong><p class="page-subtitle">{{selectedMission.scope}}</p><span class="status-badge" :class="approvedLead(selectedMission)?'approved':'pending'">{{approvedLead(selectedMission)?'Accès approuvé actif':'Accès non actif'}}</span></article><p class="module-disclaimer">Les affectations et leur approbation appartiennent au module 01. Aucun participant n’obtient de droits par sa simple présence sur la mission.</p></template>
<template v-else-if="tab==='Diagnostic'"><div class="detail-meta"><strong>Diagnostic initial · grille fictive v1</strong><span class="status-badge" :class="selectedMission.diagnosisShared?'shared':'draft'">{{selectedMission.diagnosisShared?'Partagé · figé':'Préparation'}}</span></div><p class="module-disclaimer">Questions d’exemple, sans barème ni taux de conformité. « Non évalué » n’est jamais compté comme conforme.</p><p v-if="!selectedMission.diagnosisShared&&!companyMode" class="empty-state">Le diagnostic en préparation n’a pas encore été partagé.</p><template v-else><article v-for="(d,i) in selectedMission.diagnosis" :key="i" class="diagnosis-row"><label>{{i+1}}. {{d.question}}<select v-if="companyMode&&!selectedMission.diagnosisShared" v-model="d.answer"><option v-for="(label,key) in answerLabels" :key="key" :value="key">{{label}}</option></select><strong v-else class="answer-text">{{answerLabels[d.answer]}}</strong></label><label v-if="companyMode&&!selectedMission.diagnosisShared">Justification / constat<textarea v-model="d.reason" rows="2" :required="d.answer==='not_applicable'"/></label><p v-else-if="d.reason" class="page-subtitle">{{d.reason}}</p></article><button v-if="companyMode&&!selectedMission.diagnosisShared" class="button secondary" @click="saveDiagnosisDraft">Enregistrer le brouillon</button> <button v-if="companyMode&&!selectedMission.diagnosisShared" class="button primary" @click="confirm('diagnosis','Valider et partager le diagnostic fictif')">Valider et partager</button></template></template>
<template v-else-if="tab==='Plan et actions'"><h3>Une seule source pour les actions</h3><p class="page-subtitle">Le moteur transversal du module 04 n’est pas encore livré. Aucun plan fictif ne crée de copie concurrente d’action ni ne qualifie automatiquement une non-conformité.</p><div class="module-callout"><AppIcon name="info"/><p>La liaison mission → action et le plan versionné restent à développer. Le suivi qualité existant est indépendant de cette démonstration.</p></div><RouterLink class="button secondary" to="/qualite" @click="missionOpen=false">Consulter le suivi qualité existant</RouterLink></template>
<template v-else-if="tab==='Visites'"><div class="section-toolbar"><h3>Interventions</h3><button v-if="companyMode&&selectedMission.status==='active'" class="button primary small" @click="newEditor('visit')">Planifier une intervention</button></div><article v-for="v in selectedMission.visits" :key="v.id" class="detail-card"><div class="section-toolbar"><strong>{{v.title}}</strong><span class="status-badge" :class="v.status">{{visitLabels[v.status]}}</span></div><p class="page-subtitle">{{day(v.start)}} · {{v.start.slice(11)}}–{{v.end.slice(11)}} · {{v.mode}} · Africa/Porto-Novo</p><p v-if="v.report" class="review-note">{{v.report}}</p><ul v-if="v.history.length" class="plain-history"><li v-for="(h,i) in v.history" :key="i">{{h}}</li></ul><div class="module-links"><button v-if="!companyMode&&v.status==='proposed'" class="button primary small" @click="selectedVisit=v;confirm('visit-confirm','Confirmer cette intervention ?')">Confirmer</button><template v-if="companyMode&&['proposed','confirmed'].includes(v.status)"><button class="button secondary small" @click="selectedVisit=v;newEditor('reschedule')">Reporter</button><button class="button secondary small" @click="selectedVisit=v;confirm('visit-cancel','Annuler cette intervention ?')">Annuler l’intervention</button><button v-if="v.status==='confirmed'" class="button primary small" @click="selectedVisit=v;confirm('visit-complete','Réaliser et partager un compte rendu fictif')">Saisir le compte rendu</button></template></div></article><p v-if="!selectedMission.visits.length" class="empty-state">Aucune intervention planifiée.</p></template>
<template v-else-if="tab==='Livrables'"><div class="section-toolbar"><h3>Contenus partagés</h3><button v-if="companyMode&&selectedMission.status==='active'" class="button primary small" @click="newEditor('deliverable')">Partager un exemple</button></div><p class="module-disclaimer">Contenus textuels fictifs uniquement. Le dépôt privé de fichiers, le versionnement documentaire et les modèles officiels attendent le module 03.</p><article v-for="d in selectedMission.deliverables" :key="d.id" class="detail-card"><div class="section-toolbar"><strong>{{d.title}} · v{{d.version}}</strong><span class="status-badge" :class="d.status">{{d.status==='shared'?'Partagé':d.status==='accepted'?'Accepté':'Refusé'}}</span></div><p class="document-content">{{d.content}}</p><p v-if="d.decision" class="review-note">{{d.decision}}</p><div v-if="!companyMode&&d.status==='shared'" class="module-links"><button class="button primary small" @click="selectedDeliverable=d;confirm('deliverable:accepted','Accepter ce livrable ?')">Accepter</button><button class="button secondary small" @click="selectedDeliverable=d;confirm('deliverable:refused','Refuser ce livrable ?')">Refuser avec motif</button></div></article><p v-if="!selectedMission.deliverables.length" class="empty-state">Aucun livrable partagé.</p></template>
<template v-else-if="tab==='Échanges'"><p class="module-disclaimer">Messages partagés avec l’officine uniquement. Les notes internes d’entreprise ne sont pas implémentées dans cette démo. Ce fil n’est pas un canal d’urgence.</p><article v-for="c in selectedMission.comments" :key="c.id" class="comment-card"><strong>{{c.author}}</strong><small>{{day(c.date)}}</small><p>{{c.text}}</p></article><form v-if="!['closed','refused'].includes(selectedMission.status)" @submit.prevent="sendComment" class="comment-form"><label>Message partagé<textarea v-model="comment" required maxlength="2000" rows="3"/></label><button class="button primary">Publier le message fictif</button></form></template>
<template v-else><ol class="event-list"><li v-for="e in missionEvents" :key="e.id"><span class="event-dot"></span><div><strong>{{e.title}}</strong><small>{{day(e.date)}} · {{e.actor}}</small></div></li></ol><p v-if="!missionEvents.length" class="empty-state">Aucun événement depuis le début de cette simulation.</p></template></div></template>
<template #footer><button class="button secondary" @click="missionOpen=false">Fermer</button><template v-if="selectedMission"><template v-if="!companyMode&&selectedMission.status==='proposed'"><button class="button secondary" @click="confirm('mission:draft','Demander une modification de la proposition')">Demander une modification</button><button class="button secondary" @click="confirm('mission:refused','Refuser cette mission ?')">Refuser</button><button class="button primary" @click="confirm('mission:accepted','Accepter cette proposition de mission ?')">Accepter la mission</button></template><template v-if="companyMode"><button v-if="selectedMission.status==='draft'" class="button secondary" @click="editDraftMission">Modifier le brouillon</button><button v-if="selectedMission.status==='draft'" class="button primary" @click="confirm('mission:proposed','Proposer cette mission à l’officine ?')">Proposer à l’officine</button><button v-if="['accepted','suspended'].includes(selectedMission.status)" class="button primary" @click="confirm('mission:active','Démarrer ou reprendre cette mission ?')">{{selectedMission.status==='suspended'?'Reprendre':'Démarrer'}}</button><template v-if="selectedMission.status==='active'"><button class="button secondary" @click="confirm('mission:suspended','Suspendre la mission ?')">Suspendre</button><button class="button primary" @click="confirm('mission:review','Passer la mission en bilan ?')">Préparer le bilan</button></template><template v-if="selectedMission.status==='review'"><button class="button secondary" @click="newEditor('summary')">Rédiger le bilan</button><button class="button primary" @click="confirm('mission:closed','Clôturer la mission ?')">Clôturer</button></template></template></template></template></AppModal>
<AppModal v-model="editor" :title="({request:'Demander un accompagnement',mission:'Nouvelle mission','mission-edit':'Modifier le brouillon de mission',visit:'Planifier une intervention',reschedule:'Reporter une intervention',deliverable:'Partager un livrable fictif',summary:'Rédiger et partager le bilan'} as Record<string,string>)[kind]" size="wide"><form id="support-editor" class="form-body form-grid" @submit.prevent="save()"><p v-if="error" class="alert error span-2" role="alert">{{error}}</p><p class="context-label span-2">{{currentOffice.name}} · données fictives uniquement</p>
<template v-if="kind==='request'"><label class="span-2">Intitulé du besoin<input v-model="form.title" maxlength="150" required/></label><label>Thème<select v-model="form.theme"><option>Qualité & procédures</option><option>Organisation</option><option>Diagnostic initial</option><option>Autre besoin</option></select></label><label>Contact<input v-model="form.contact" required maxlength="150"/></label><label class="span-2">Description et contexte<textarea v-model="form.description" required maxlength="4000" rows="4"/></label><label>Disponibilités souhaitées<input v-model="form.availability"/></label><label>Urgence déclarée<select v-model="form.urgency"><option>Normale</option><option>Élevée (déclarée)</option><option>À convenir</option></select></label></template>
<template v-else-if="kind==='mission'||kind==='mission-edit'"><label class="span-2">Intitulé de la mission<input v-model="form.title" required maxlength="150"/></label><label class="span-2">Objectifs et contexte<textarea v-model="form.objectives" required rows="3" maxlength="4000"/></label><label>Périmètre<select v-model="form.scope"><option>Accompagnement qualité</option><option>Organisation et procédures</option></select></label><label>Responsable approuvé<select v-model="form.leadId" required><option value="">Choisir</option><option v-for="a in eligibleLeads" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Début prévu<input v-model="form.start" type="date" required/></label><label>Fin prévue<input v-model="form.end" :min="form.start" type="date" required/></label><p class="module-disclaimer span-2">La mission est créée en brouillon. Sa proposition doit être acceptée dans la vue officine avant démarrage.</p></template>
<template v-else-if="kind==='visit'||kind==='reschedule'"><label v-if="kind==='visit'" class="span-2">Objet<input v-model="form.title" required maxlength="150"/></label><label>Début (Africa/Porto-Novo)<input v-model="form.start" type="datetime-local" required/></label><label>Fin (Africa/Porto-Novo)<input v-model="form.end" type="datetime-local" :min="form.start" required/></label><label v-if="kind==='visit'">Mode<select v-model="form.mode"><option>Présentiel</option><option>À distance</option></select></label><label v-else class="span-2">Motif du report<textarea v-model="form.reason" required rows="3"/></label><p class="module-disclaimer span-2">L’intervention sera proposée à l’officine pour confirmation. En cas de report, l’ancien horaire est conservé.</p></template>
<template v-else-if="kind==='deliverable'"><label class="span-2">Titre<input v-model="form.title" required maxlength="150"/></label><label class="span-2">Contenu fictif partagé<textarea v-model="form.content" required maxlength="5000" rows="6"/></label></template>
<template v-else><label class="span-2">Synthèse et recommandations<textarea v-model="form.content" required rows="5" maxlength="5000"/></label><label class="span-2">Décision explicite sur les actions ouvertes<textarea v-model="form.reason" required rows="3" placeholder="Responsables, transfert ou maintien au suivi…"/></label><p class="module-disclaimer span-2">La clôture ne marque aucune action comme réalisée et ne retire aucun accès accompagnateur.</p></template>
</form><template #footer><button class="button secondary" @click="editor=false">Annuler</button><button v-if="kind==='request'" class="button secondary" @click="save(true)">Enregistrer le brouillon</button><button class="button primary" form="support-editor" type="submit">{{kind==='request'?'Soumettre la demande':kind==='mission'?'Créer le brouillon':kind==='mission-edit'?'Enregistrer le brouillon':'Enregistrer et partager'}}</button></template></AppModal>
<AppModal v-model="confirmation" :title="actionTitle" size="small"><form id="support-confirm" class="form-body" @submit.prevent="execute"><p v-if="error" class="alert error" role="alert">{{error}}</p><p>Cette décision est enregistrée dans la démonstration locale uniquement.</p><label v-if="['request:clarifications','request:refused','request:withdrawn','mission:refused','mission:draft','mission:suspended','visit-cancel','visit-complete','deliverable:refused'].includes(command)||(command==='request:submitted'&&selectedRequest?.status==='clarifications')">{{command==='visit-complete'?'Compte rendu partagé':command==='request:submitted'?'Votre réponse':'Message ou motif partagé'}}<textarea v-model="message" required rows="4" maxlength="3000"/></label></form><template #footer><button class="button secondary" @click="confirmation=false">Annuler</button><button class="button primary" form="support-confirm" type="submit">Confirmer</button></template></AppModal>
</template></section></template>
